UPDATE `locales_quest` SET `title_loc11`='Recupera OOX-09/HL!' WHERE `entry`=836;
UPDATE `locales_quest` SET `title_loc11`='Coscritto dell\'Orda',`details_loc11`='Mmm, sembri molto forte.$B$BAscolta... il mio buon amico Kargal ha bisogno di nuove reclute da assegnare nelle Savane. So che ci tieni a fare quello che è giusto per l\'Orda e questa è l\'occasione per dimostrarlo.$B$BConsegna questa Lettera di Reclutamento a Kargal e fai in modo che la firmi.' WHERE `entry`=840;
