UPDATE `locales_quest` SET `title_loc11`='Cartapecora codificata',`details_loc11`='Ah. Mentre eri via $N, ti è arrivata della posta.$B$BQuando hai tempo, dagli una lettura. Se non mi sbaglio proviene da Rwag, l\'Istruttore dei Ladri. Quando sarai disponibile, vorrebbe scambiare due parole con te.',`objectives_loc11`='Leggi la Cartapecora Codificata e parla con Rwag nella Valle delle Sfide.' WHERE `entry`=3088;
