UPDATE `locales_quest` SET `title_loc11`='Sigillo Intagliato',`details_loc11`='Questo sigillo mi è stato dato da un messaggero della nostra Istruttrice dei Cacciatori, Ayanna. Sembra che voglia parlare con te quando hai un attimo di tempo. Leggilo e portaglielo.' WHERE `entry`=3117;
