UPDATE `locales_quest` SET `title_loc11`='Paraspalle della Falce Ossuta',`objectives_loc11`='[Rohan the Assassin at Light\'s Hope Chapel in the Eastern Plaguelands will make Bonescythe Pauldrons if you bring him the following: 1 Desecrated Pauldrons, 12 Wartorn Leather Scraps, 5 Cured Rugged Hides, 1 Nexus Crystal and 50 gold pieces. ]' WHERE `entry`=9080;
