UPDATE `locales_quest` SET `title_loc11`='Contratto d\'Artigianato: Sacca di Telarunica' WHERE `entry`=9191;
UPDATE `locales_quest` SET `title_loc11`='Problemi nelle Miniere Fiocaluce',`details_loc11`='Le Miniere Fiocaluce a sud-ovest sono state prese d\'assalto da un clan di Gnoll, gli Zampanera. Non c\'è bisogno di ricordarti l\'importanza strategica di quelle miniere per la nostra campagna qui nelle Terre Spettrali!$B$BSegui la strada a sud fuori dal villaggio e al bivio svolta a destra. Una volta superata la Ziggurat sulla destra vedrai un sentiero sterrato a ovest. Percorrilo.$B$BDobbiamo tornare a estrarre il minerale!',`objectives_loc11`='Uccidi 8 Gnoll Zampanera, 6 Saprofagi Zampanera e 4 Sciamani Zampanera, dopodiché torna dall\'Inseguitore della Morte Maltendis a Tranquillien nelle Terre Spettrali.' WHERE `entry`=9192;
UPDATE `locales_quest` SET `title_loc11`='Esplorare le Catacombe degli Amani',`offerrewardtext_loc11`='Disgustoso, ma necessario posso assicurarti. Ci hai fatto un buon servizio investigando su questo argomento, per favore, prendi questo come segno della nostra generosità e apprezzamento.' WHERE `entry`=9193;
UPDATE `locales_quest` SET `EndText_loc11`='Esplorare le Catacombe degli Amani' WHERE `entry`=9193;
UPDATE `locales_quest` SET `title_loc11`='Contratto d\'Artigianato: Tonaca di Telarunica' WHERE `entry`=9194;
