UPDATE `locales_quest` SET `title_loc11`='Il patto del Saggio',`details_loc11`='$N, le tue imprese sono andate al di là delle mie aspettative.$B$BTi muovi tra le pieghe del tempo con la familiarità di un Drago Bronzeo. Sei $Gdestinato:destinata; a ottenere grandi poteri e io sono più che lieta di aiutarti.$B$BContinua a servire le Scaglie delle Sabbie e io ti aiuterò a realizzare il tuo potenziale.',`objectives_loc11`='Porta la tua Vera dell\'Eternità a Soridormi nelle Caverne del Tempo dopo aver acquisito la reputazione Osannato con le Scaglie delle Sabbie.' WHERE `entry`=10472;
