UPDATE `locales_quest` SET `title_loc11`='Il caro estinto',`details_loc11`='È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!$B$BPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.$B$BChapman vende la ricetta, se non sbaglio.',`objectives_loc11`='Ottieni del Pane dei Morti e consegnalo allo Spirito Elfo del Sangue Allegro nel Cimitero di Lunargenta.$B$BUsa una Calendula Arancione per vedere gli spiriti invisibili.' WHERE `entry`=14171;
