UPDATE `locales_quest` SET `title_loc11`='Parla con Spraggle',`details_loc11`='È un po\' di tempo che la mia amica Spraggle si sta rodendo il fegato per qualche motivo. L\'aiuterei volentieri, ma come puoi vedere sono impegnato.$B$BPotresti andare a parlarle per scoprire cosa le serve?',`objectives_loc11`='Parla con Spraggle Pinzapersa all\'Accampamento dei Grant.' WHERE `entry`=24794;
